// The welcome screen's transitions into the menu (owner and manager via Kian, 2026-10-10; names, levels, durations and descriptions
// in src/lib/transitions.ts). Server only: this module builds the CSS and the inline script of one concept for one season; the page
// (src/pages/senso.tsx through src/components/Welcome.tsx) ships only the venue's selected concept for the season it is rendered for,
// and the admin's scene API returns any concept for the preview. Nothing of the other concepts reaches customers.
//
// How a transition runs. The tap (welcomeScript in Welcome.tsx) applies the language first (before anything moves), stores it,
// makes the menu reachable again (inert off) and sets the overlay to "done": from that moment the overlay lets every tap and scroll
// through to the menu (pointer-events none, public.css), so the menu is usable at once and the transition only reveals it. Then it
// calls w.rosesTx(off, reduced), defined here: under reduced motion a 150 ms fade of the whole overlay; otherwise the overlay is kept
// visible (.tx), its cream moves to a panel of its own (.txb) so the menu can show behind the scene and the card, the concept animates,
// and `off` (display none) runs when the concept's time is up (≤ 900 ms). Motion is the Web Animations API on transform and opacity
// only (the individual transform properties scale and rotate included), so it runs on the compositor and leaves the scene's own CSS
// animations (fall, sway, flutter on .y/.s/.w) untouched: a particle (.p) is moved as a whole, its inner .s turned or shrunk around
// the particle's visual centre. Every animation is kept in A and cancelled at the end, so the admin preview can play it again.
// Season-native (spring and summer since 2026-10-11, below): fall concepts use the picked leaves (F1, F2, F4, F8, F9; the symbols the page already carries) and leaf motion
// (tumbling, fluttering, settling); winter concepts the picked snowflakes (W1, W3, W5, W7, W10) in the Winter snow token and snow
// motion (melting, drifting, blowing, frost). Colours: the Welcome group's tokens, and the artwork palette for white and frost
// (src/venues/tokens.ts ARTWORK; this file holds no colour literal). Each concept ≤ 3 KB gzipped, checked by the transition drill.
import { ARTWORK } from '@/venues/tokens';
import { REDUCED_MS, TRANSITION_BY_ID, type TransitionId, type TxSeason } from '@/lib/transitions';

export type TxCode = { id: TransitionId; season: TxSeason; key: string; css: string; js: string };
// key: the concept and season named in the page (data-tx on the style element, w.rosesTxKey), e.g. "T5-fall".

// The parts every concept shares. CSS: the overlay kept visible while it plays (the "done" state of public.css fades it in 200 ms),
// the cream on its own panel, the layer for the concept's own elements. Placeholders in the script: @K (the key), @CAP (the latest end).
const BASE_CSS = 'html #welcome.tx,html #welcome.rm{opacity:1;visibility:visible;transition:none}#welcome.tx{background:none}'
  + '.txb,.txl{position:absolute;inset:0;pointer-events:none}.txb{background:var(--c-welcome-bg)}.txl i,.txl b{position:absolute;display:block}.txl svg{display:block;width:100%;height:100%;overflow:visible}'
  + '#welcome.tp .scene .y,#welcome.tp .scene .s,#welcome.tp .scene .w{animation-play-state:paused}';
// The prelude (the overlay goes when the concept's last animation has finished, so nothing is cut, and never later than CAP ms after
// the tap, so the whole transition stays within Kian's 900 ms even when the phone starts the animations late). The tap's own task
// only keeps the overlay up (.tx); the concept is set up in the next frame (requestAnimationFrame, before that frame is drawn, so
// nothing shows in between), so the page's restyle after the tap and the concept's setup never add up to one long task (measured at
// CPU 4×, 2026-10-10: in one task T9's tap reached 51–57 ms now and then): z() starts an animation (fill both by default) and keeps it; end() hides the overlay and cancels everything; R()
// random; ps the particles, sv(p) a particle's inner box (its visual centre), pos(e) an element's centre on the screen; lay(h, top)
// adds a layer of the concept's own elements under the card (at 1: over everything; at 2: under the scene); use() one artwork symbol as an element; pick() a random
// picked design of the scene; dp(p) the particle's depth (0 far, 1 middle, 2 near); EI/EO/EIO easings (in, out, in-out). Every
// position a concept needs is read here, before the prelude or the concept writes anything, so the tap costs one style and layout
// pass, not two (measured at CPU 4×, 2026-10-10: T9's setup 38–49 ms with the second pass): P0[i] the centre of particle i, GR and HR
// the welcome logo's and the header logo's boxes (G, HL the elements), BP the centre of the tapped language button.
const PRELUDE = `(function(){var w=document.getElementById('welcome');if(!w)return;var A=[];w.rosesTxKey='@K';
w.rosesTx=function(off,rm){if(/\\b(tx|rm)\\b/.test(w.className))return;A.forEach(function(a){a.cancel()});A=[];[].forEach.call(w.querySelectorAll('.txb,.txl'),function(e){e.remove()});
var n=w.rosesTxRun=(w.rosesTxRun||0)+1,ts=performance.now(),z=function(e,k,o){if(!e)return;o.fill=o.fill||'both';var a=e.animate(k,o);A.push(a);return a},end=function(){if(n!==w.rosesTxRun)return;w.rosesTxRun++;off();w.classList.remove('tx','rm','tp');A.forEach(function(a){a.cancel()});A=[]},
fin=function(c){setTimeout(end,M.max(0,c-(performance.now()-ts)));Promise.all(A.map(function(a){return a.finished})).then(end,function(){})},M=Math;
if(rm){w.classList.add('rm');z(w,{opacity:[1,0]},{duration:${REDUCED_MS},easing:'linear'});fin(${REDUCED_MS * 2});return}
w.classList.add('tx');requestAnimationFrame(function(){if(n!==w.rosesTxRun)return;
var W=innerWidth,H=innerHeight,R=function(a,b){return a+Math.random()*(b-a)},I=function(n){return M.round(n)},
ps=[].slice.call(w.querySelectorAll('.scene .p')),c=w.querySelector('.welcome-card'),sc=w.querySelector('.welcome-scene'),
sv=function(p){return p.firstChild&&p.firstChild.firstChild},pos=function(e){var r=e.getBoundingClientRect();return[r.left+r.width/2,r.top+r.height/2]},
dp=function(p){return/near/.test(p.className)?2:/mid/.test(p.className)?1:0},sn=w.querySelector('.scene'),D=((sn&&sn.getAttribute('data-designs'))||'').split(','),
pick=function(){return D[M.floor(M.random()*D.length)]},use=function(x,y,s,id,st){s=I(s);return'<i style="left:'+I(x-s/2)+'px;top:'+I(y-s/2)+'px;width:'+s+'px;height:'+s+'px'+(st||'')+'"><svg viewBox="0 0 64 64"><use href="#'+id+'"/></svg></i>'},
lay=function(h,at,k){var l=document.createElement('div');l.className='txl'+(k?' '+k:'');l.innerHTML=h;w.insertBefore(l,at==1?null:at==2?sc:c);return[].slice.call(l.children)},
EI='cubic-bezier(.55,0,.85,.3)',EO='cubic-bezier(.2,.8,.2,1)',EIO='cubic-bezier(.65,0,.35,1)',
P0=ps.map(function(p){return pos(sv(p))}),G=c&&c.querySelector('img'),HL=document.querySelector('main > header img'),GR=G&&G.getBoundingClientRect(),HR=HL&&HL.getBoundingClientRect(),
BT=w.querySelector('button[data-lang="'+document.documentElement.dataset.lang+'"]'),BP=BT&&pos(BT),b=document.createElement('div');b.className='txb';w.insertBefore(b,w.firstChild);
@BODY
fin(@CAP)})}})();`;

// Shared moves of the card and the cream: fade, with a small shift.
const cardOut = (t: string, ms: number, delay = 0, ease = "'cubic-bezier(.4,0,1,1)'") => `z(c,{opacity:0,transform:'${t}'},{duration:${ms},delay:${delay},easing:${ease}});`;
