const squeeze = (s: string) => s.replace(/\n\s*/g, '');
// The latest the overlay goes, from the tap (Kian's ruling: the whole transition ≤ 900 ms; the timer's own lateness stays inside the rest).
export const CAP_MS = 880;
// One concept for one season, as the page ships it (fall and winter since 2026-10-10, spring and summer since 2026-10-11).
export function transitionCode(id: TransitionId, season: TxSeason): TxCode | null {
  const def = TRANSITION_BY_ID[id], concept = season === 'spring' || season === 'summer' ? WARM[id]?.[season] : CONCEPTS[id]?.[season];
  if (!def || !concept) return null;
  const key = `${id}-${season}`;
  const js = squeeze(PRELUDE).replace('@K', key).replace('@BODY', () => concept.js).replace('@CAP', String(CAP_MS));
  return { id, season, key, css: BASE_CSS + (concept.css ?? ''), js };
}
